def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0]), fmt([1, 2]), fmt([2, 1]), fmt([3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
             fmt([7, 1, 5, 3, 6, 4]), fmt([1, 5, 1, 5, 1, 5]), fmt([0, 10000, 0, 10000])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            tests.append(fmt([rng.randint(0, 20) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(0, 10000) for _ in range(rng.randint(10, 40))]))
    N = 100000
    tests.append(fmt([rng.randint(0, 10000) for _ in range(N)]))
    tests.append(fmt([10000 * (i % 2) for i in range(N)]))
    tests.append(fmt([min(10000, i // 10) for i in range(N)]))
    return tests
